changes.old:
static bool HandleNpcSetMoveTypeCommand(ChatHandler* handler, const char* args)
{
    if (!*args)
        return false;

    // 3 arguments:
    // GUID (optional - you can also select the creature)
    // stay|random|way (determines the kind of movement)
    // NODEL (optional - tells the system NOT to delete any waypoints)
    //        this is very handy if you want to do waypoints, that are
    //        later switched on/off according to special events (like escort
    //        quests, etc)
    char* guid_str = strtok((char*)args, " ");
    char* type_str = strtok((char*)NULL, " ");
    char* dontdel_str = strtok((char*)NULL, " ");

    bool doNotDelete = false;

    if (!guid_str)
        return false;

    uint32 lowguid = 0;
    Creature* creature = NULL;

    if (dontdel_str)
    {
        //TC_LOG_ERROR("misc", "DEBUG: All 3 params are set");

        // All 3 params are set
        // GUID
        // type
        // doNotDEL
        if (stricmp(dontdel_str, "NODEL") == 0)
        {
            //TC_LOG_ERROR("misc", "DEBUG: doNotDelete = true;");
            doNotDelete = true;
        }
    }
    else
    {
        // Only 2 params - but maybe NODEL is set
        if (type_str)
        {
            TC_LOG_ERROR("misc", "DEBUG: Only 2 params ");
            if (stricmp(type_str, "NODEL") == 0)
            {
                //TC_LOG_ERROR("misc", "DEBUG: type_str, NODEL ");
                doNotDelete = true;
                type_str = NULL;
            }
        }
    }

    if (!type_str)                                           // case .setmovetype $move_type (with selected creature)
    {
        type_str = guid_str;
        creature = handler->getSelectedCreature();
        if (!creature || creature->isPet())
            return false;
        lowguid = creature->GetDBTableGUIDLow();
    }
    else                                                    // case .setmovetype #creature_guid $move_type (with selected creature)
    {
        lowguid = strtoull(guid_str, nullptr, 10);

        /* impossible without entry
        if (lowguid)
            creature = ObjectAccessor::GetCreature(*handler->GetSession()->GetPlayer(), MAKE_GUID(lowguid, HighGuid::Creature));
        */

        // attempt check creature existence by DB data
        if (!creature)
        {
            CreatureData const* data = sObjectMgr->GetCreatureData(lowguid);
            if (!data)
            {
                handler->PSendSysMessage(LANG_COMMAND_CREATGUIDNOTFOUND, lowguid);
                handler->SetSentErrorMessage(true);
                return false;
            }
        }
        else
        {
            lowguid = creature->GetDBTableGUIDLow();
        }
    }

    // now lowguid is low guid really existed creature
    // and creature point (maybe) to this creature or NULL

    MovementGeneratorType move_type;

    std::string type = type_str;

    if (type == "stay")
        move_type = IDLE_MOTION_TYPE;
    else if (type == "random")
        move_type = RANDOM_MOTION_TYPE;
    else if (type == "way")
        move_type = WAYPOINT_MOTION_TYPE;
    else
        return false;

    // update movement type
    //if (doNotDelete == false)
    //    WaypointMgr.DeletePath(lowguid);

    if (creature)
    {
        // update movement type
        if (doNotDelete == false)
            creature->LoadPath(0);

        creature->SetDefaultMovementType(move_type);
        creature->GetMotionMaster()->Initialize();
        if (creature->IsAlive())                            // dead creature will reset movement generator at respawn
        {
            creature->setDeathState(JUST_DIED);
            creature->Respawn();
        }
        creature->SaveToDB();
    }
    if (doNotDelete == false)
    {
        handler->PSendSysMessage(LANG_MOVE_TYPE_SET, type_str);
    }
    else
    {
        handler->PSendSysMessage(LANG_MOVE_TYPE_SET_NODEL, type_str);
    }

    return true;
}

