    if (nameStr)
    {
        name = nameStr;
        // normalize the name if specified and check if it exists
        if (!normalizePlayerName(name))
        {
            handler->PSendSysMessage(LANG_INVALID_CHARACTER_NAME);
            handler->SetSentErrorMessage(true);
            return false;
        }

        if (sCharacterDataStore->CheckPlayerName(name, handler->GetSessionDbcLocale(), true) != CHAR_NAME_SUCCESS)
        {
            handler->PSendSysMessage(LANG_INVALID_CHARACTER_NAME);
            handler->SetSentErrorMessage(true);
            return false;
        }

        guidStr = strtok(NULL, " ");
    }

    ObjectGuid::LowType LowGuid = 0;
    ObjectGuid guid;
    if (guidStr)
    {
        if (!Trinity::ParseCommandInteger(guidStr, LowGuid) || !LowGuid || LowGuid > ObjectGuid::GetMaxCounter(HighGuid::Player))
        {
            handler->PSendSysMessage(LANG_INVALID_CHARACTER_GUID);
            handler->SetSentErrorMessage(true);
            return false;
        }
        guid = ObjectGuid::Create<HighGuid::Player>(LowGuid);
        if (ObjectMgr::GetPlayerAccountIdByGUID(guid))
        {
            handler->PSendSysMessage("Character GUID " UI64FMTD " is already in use.", LowGuid);
            handler->SetSentErrorMessage(true);
            return false;
        }
    }

    switch (PlayerDumpReader().LoadDump(fileStr, accountId, name, guid.GetGUIDLow()))
    {
        case DUMP_SUCCESS:
            handler->PSendSysMessage(LANG_COMMAND_IMPORT_SUCCESS);
            break;
        case DUMP_FILE_OPEN_ERROR:
            handler->PSendSysMessage(LANG_FILE_OPEN_FAIL, fileStr);
            handler->SetSentErrorMessage(true);
            return false;
        case DUMP_FILE_BROKEN:
            handler->PSendSysMessage(LANG_DUMP_BROKEN, fileStr);
            handler->SetSentErrorMessage(true);
            return false;
        case DUMP_TOO_MANY_CHARS:
            handler->PSendSysMessage(LANG_ACCOUNT_CHARACTER_LIST_FULL, accountName.c_str(), accountId);
            handler->SetSentErrorMessage(true);
            return false;
        default:
            handler->PSendSysMessage(LANG_COMMAND_IMPORT_FAILED);
            handler->SetSentErrorMessage(true);
            return false;
    }

    return true;
}

extra_edits.old:
void Player::DeleteOldCharacters(uint32 keepDays)
{
    TC_LOG_INFO("entities.player", "Player::DeleteOldChars: Deleting all characters which have been deleted %u days before...", keepDays);

    CharacterDatabasePreparedStatement* stmt = CharacterDatabase.GetPreparedStatement(CHAR_SEL_CHAR_OLD_CHARS);
    stmt->setUInt32(0, uint32(GameTime::GetGameTime() - time_t(keepDays * DAY)));
    PreparedQueryResult result = CharacterDatabase.Query(stmt);

    if (result)
    {
         TC_LOG_DEBUG("entities.player", "Player::DeleteOldChars: Found " UI64FMTD " character(s) to delete", result->GetRowCount());
         do
         {
            Field* fields = result->Fetch();
            Player::DeleteFromDB(ObjectGuid::Create<HighGuid::Player>(fields[0].GetUInt64()), fields[1].GetUInt32(), true, true);
         }
         while (result->NextRow());
    }
}

extra_edits.new:
void Player::DeleteOldCharacters(uint32 keepDays)
{
    TC_LOG_INFO("entities.player", "Player::DeleteOldChars: Deleting all characters which have been deleted %u days before...", keepDays);

    time_t now = GameTime::GetGameTime();
    uint64 retention = uint64(keepDays) * DAY;
    if (now <= 0 || retention >= uint64(now))
        return;

    CharacterDatabasePreparedStatement* stmt = CharacterDatabase.GetPreparedStatement(CHAR_SEL_CHAR_OLD_CHARS);
    stmt->setUInt64(0, uint64(now) - retention);
    PreparedQueryResult result = CharacterDatabase.Query(stmt);

    if (result)
    {
         TC_LOG_DEBUG("entities.player", "Player::DeleteOldChars: Found " UI64FMTD " character(s) to delete", result->GetRowCount());
         do
         {
            Field* fields = result->Fetch();
            Player::DeleteFromDB(ObjectGuid::Create<HighGuid::Player>(fields[0].GetUInt64()), fields[1].GetUInt32(), true, true);
         }
         while (result->NextRow());
    }
}
